import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Reusable Font Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// SVG Icon Component for Stacking Tubs
const StackingTubsIcon: React.FC<{
  frame: number;
  fps: number;
  color: string;
  delayStart: number;
}> = ({ frame, fps, color, delayStart }) => {
  const tubHeight = 40;
  const tubWidth = 70;
  const spacing = 10;

  // Staggered springs for 3 tubs
  const tub1Spring = spring({ frame: frame - delayStart, fps, config: { damping: 12 } });
  const tub2Spring = spring({ frame: frame - (delayStart + 5), fps, config: { damping: 12 } });
  const tub3Spring = spring({ frame: frame - (delayStart + 10), fps, config: { damping: 12 } });

  const tubs = [
    { scale: tub1Spring, yOffset: 0 },
    { scale: tub2Spring, yOffset: -(tubHeight + spacing) },
    { scale: tub3Spring, yOffset: -(tubHeight + spacing) * 2 },
  ];

  return (
    <div style={{ position: "relative", width: tubWidth, height: tubHeight * 3 + spacing * 2 }}>
      {tubs.map((tub, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            width: tubWidth,
            height: tubHeight,
            backgroundColor: i === 2 ? color : "#e0e0e0", // Top one is colored
            borderRadius: 6,
            transform: `translateY(${tub.yOffset}px) scale(${tub.scale})`,
            opacity: tub.scale,
            boxShadow: `0 0 15px ${i === 2 ? color : "rgba(255,255,255,0.2)"}`,
            transformOrigin: "bottom center",
            zIndex: 3 - i,
          }}
        >
          {/* Lid detail */}
          <div
            style={{
              width: "105%",
              height: 8,
              backgroundColor: "rgba(0,0,0,0.3)",
              position: "absolute",
              top: -4,
              left: "-2.5%",
              borderRadius: 2,
            }}
          />
          {/* Label detail */}
          <div
            style={{
              width: "60%",
              height: "40%",
              backgroundColor: "rgba(0,0,0,0.1)",
              position: "absolute",
              top: "30%",
              left: "20%",
            }}
          />
        </div>
      ))}
    </div>
  );
};



export type FitnessLowerThirdProps = Record<string, any>;

const FitnessLowerThird: React.FC<FitnessLowerThirdProps> = ({
  backgroundColor = "#1a1a1a",
  accentColor = "#FF4500",
  titleText = "STACKING PRE-WORKOUT",
  bodyText = "Combining multiple pre-workout supplements (or individual ingredients) to customize and enhance effects—pairing stim-based formulas for energy with non-stim pump products.",
  transparentBackground = true,
  durationInSeconds = 8,
  textStartDelay = 2.0,
}) => {
  // Load Fonts
  useFontLoader(["Oswald", "Roboto Condensed"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety checks
  const safeBgColor = transparentBackground ? `${backgroundColor}CC` : backgroundColor; // ~80% opacity if transparent
  const startFrame = textStartDelay * fps;

  // --- Animations ---

  // 1. Background Bar Entrance (Slide up from bottom)
  const barEntrance = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 100 },
  });
  
  const barY = interpolate(barEntrance, [0, 1], [350, 0]);

  // 2. Text Animations (Staggered)
  const titleSpring = spring({
    frame: frame - startFrame,
    fps,
    config: { damping: 15 },
  });

  const bodySpring = spring({
    frame: frame - (startFrame + 10), // 10 frames after title
    fps,
    config: { damping: 15 },
  });

  // Text Entrance Translations
  const titleY = interpolate(titleSpring, [0, 1], [50, 0]);
  const bodyY = interpolate(bodySpring, [0, 1], [30, 0]);

  // Background "Energy" Pulse
  const pulse = Math.sin(frame / 15) * 0.5 + 0.5; // 0 to 1 oscillating
  const pulseOpacity = interpolate(pulse, [0, 1], [0.1, 0.3]);

  // Container height (Lower Third)
  const containerHeight = height * 0.35;

  return (
    <AbsoluteFill
      style={{
        justifyContent: "flex-end", // Align to bottom
        backgroundColor: transparentBackground ? "transparent" : "#000",
        fontFamily: "Roboto Condensed, sans-serif",
      }}
    >
      {/* Lower Third Container */}
      <div
        style={{
          width: "100%",
          height: containerHeight,
          position: "relative",
          overflow: "hidden",
          transform: `translateY(${barY}px)`,
        }}
      >
        {/* Background Overlay */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: safeBgColor,
            borderTop: `4px solid ${accentColor}`,
            boxShadow: `0 -10px 40px ${accentColor}40`, // Glow effect upwards
          }}
        />

        {/* Abstract Energy Waves (Background FX) */}
        <AbsoluteFill style={{ opacity: pulseOpacity }}>
          <div
            style={{
              position: "absolute",
              top: "-50%",
              left: "-10%",
              width: "120%",
              height: "200%",
              background: `repeating-linear-gradient(
                45deg,
                transparent,
                transparent 40px,
                ${accentColor}10 40px,
                ${accentColor}10 80px
              )`,
              transform: `translateX(${frame}px)`, // Subtle movement
            }}
          />
        </AbsoluteFill>

        {/* Content Layout */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            height: "100%",
            padding: "0 5%",
            position: "relative",
            zIndex: 10,
          }}
        >
          {/* Left Side: Stacking Icon */}
          <div style={{ marginRight: 60, paddingBottom: 20 }}>
            <StackingTubsIcon
              frame={frame}
              fps={fps}
              color={accentColor}
              delayStart={fps * 0.5} // Icon starts earlier than text
            />
          </div>

          {/* Right Side: Text Content */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center" }}>
            {/* Title */}
            <div
              style={{
                fontFamily: "Oswald, sans-serif",
                fontSize: 64,
                fontWeight: 700,
                color: accentColor,
                textTransform: "uppercase",
                lineHeight: 1,
                marginBottom: 10,
                opacity: titleSpring,
                transform: `translateY(${titleY}px)`,
                textShadow: `0 0 10px ${accentColor}60`,
              }}
            >
              {titleText}
            </div>

            {/* Divider Line */}
            <div
              style={{
                width: interpolate(titleSpring, [0, 1], [0, 100]) + "%",
                height: 2,
                backgroundColor: "rgba(255,255,255,0.3)",
                marginBottom: 12,
              }}
            />

            {/* Body Definition */}
            <div
              style={{
                color: "white",
                fontSize: 24,
                lineHeight: 1.4,
                opacity: bodySpring,
                transform: `translateY(${bodyY}px)`,
                maxWidth: "90%",
              }}
            >
              {bodyText}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FitnessLowerThird;